import numpy as np
from scipy import stats
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong univariate predictors
    strong_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue  # Skip derived features
        t_stat, p_val = stats.ttest_ind(feats.x[feats.y==1, i], feats.x[feats.y==0, i])
        if abs(t_stat) > 3.5 and p_val < 0.001:
            strong_features.append((fid, abs(t_stat)))

    # Sort by strength
    strong_features.sort(key=lambda x: x[1], reverse=True)

    # Select top candidates, avoiding near-duplicates
    selected = []
    excluded = set()
    for fid, _ in strong_features:
        if fid in excluded:
            continue
        selected.append(fid)
        # Remove correlated features
        for other_fid in feats.ids:
            if other_fid != fid and other_fid not in excluded:
                corr = np.corrcoef(feats.x[:, feats.column(fid)], 
                                 feats.x[:, feats.column(other_fid)])[0,1]
                if abs(corr) > 0.6:
                    excluded.add(other_fid)
        if len(selected) >= MAX_DRIVERS:
            break

    # If no strong drivers found, return empty design
    if not selected:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build regression components
    columns = selected[:]
    loadings = {}

    # Add interaction terms for top features
    products = []
    for i, fid1 in enumerate(columns[:3]):  # Limit to top 3 for interactions
        for fid2 in columns[i+1:]:
            products.append((fid1, fid2))

    # Add weighted score using mutual information
    mi_scores = mutual_info_classif(feats.x[:, [feats.column(fid) for fid in columns]], feats.y)
    for i, fid in enumerate(columns):
        loadings[fid] = mi_scores[i]

    return Design(drivers=tuple(selected), columns=tuple(columns), products=tuple(products), loadings=loadings)

